CREATE TYPE "ProductKind" AS ENUM ('READY_MADE','MADE_TO_ORDER');
CREATE TYPE "OrderStatus" AS ENUM ('PENDING','CONFIRMED','IN_PROGRESS','READY','COMPLETED','CANCELLED');
CREATE TYPE "CustomStatus" AS ENUM ('PENDING_REVIEW','CONTACTED','QUOTED','ACCEPTED','IN_PROGRESS','READY','COMPLETED','REJECTED');
CREATE TABLE "AdminUser"("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Product"("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"description" TEXT NOT NULL,"price" DECIMAL(10,2) NOT NULL CHECK("price">0),"category" TEXT NOT NULL,"collection" TEXT,"fabric" TEXT,"colour" TEXT,"sizes" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],"stock" INTEGER NOT NULL DEFAULT 0 CHECK("stock">=0),"kind" "ProductKind" NOT NULL DEFAULT 'READY_MADE',"featured" BOOLEAN NOT NULL DEFAULT false,"newArrival" BOOLEAN NOT NULL DEFAULT false,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "Product_active_category_idx" ON "Product"("active","category"); CREATE INDEX "Product_featured_active_idx" ON "Product"("featured","active");
CREATE TABLE "ProductImage"("id" TEXT PRIMARY KEY,"productId" TEXT NOT NULL REFERENCES "Product"("id") ON DELETE CASCADE,"storageKey" TEXT NOT NULL,"url" TEXT NOT NULL,"alt" TEXT,"sortOrder" INTEGER NOT NULL DEFAULT 0); CREATE INDEX "ProductImage_productId_idx" ON "ProductImage"("productId");
CREATE TABLE "ReadyOrder"("id" TEXT PRIMARY KEY,"reference" TEXT NOT NULL UNIQUE,"customerName" TEXT NOT NULL,"phone" TEXT NOT NULL,"email" TEXT,"deliveryArea" TEXT NOT NULL,"instructions" TEXT,"status" "OrderStatus" NOT NULL DEFAULT 'PENDING',"internalNotes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL); CREATE INDEX "ReadyOrder_status_createdAt_idx" ON "ReadyOrder"("status","createdAt");
CREATE TABLE "OrderItem"("id" TEXT PRIMARY KEY,"orderId" TEXT NOT NULL REFERENCES "ReadyOrder"("id") ON DELETE CASCADE,"productId" TEXT REFERENCES "Product"("id") ON DELETE SET NULL,"productName" TEXT NOT NULL,"size" TEXT NOT NULL,"quantity" INTEGER NOT NULL CHECK("quantity">0),"unitPrice" DECIMAL(10,2) NOT NULL);
CREATE TABLE "CustomRequest"("id" TEXT PRIMARY KEY,"reference" TEXT NOT NULL UNIQUE,"customerName" TEXT NOT NULL,"phone" TEXT NOT NULL,"email" TEXT,"garmentType" TEXT NOT NULL,"description" TEXT NOT NULL,"fabric" TEXT,"colour" TEXT,"neckDesign" TEXT,"sleeveDesign" TEXT,"preferredSize" TEXT,"measurements" JSONB,"quantity" INTEGER NOT NULL DEFAULT 1 CHECK("quantity">0),"budget" TEXT,"preferredDate" TIMESTAMP(3),"deliveryArea" TEXT NOT NULL,"instructions" TEXT,"quotedPrice" DECIMAL(10,2),"agreedDeliveryDate" TIMESTAMP(3),"status" "CustomStatus" NOT NULL DEFAULT 'PENDING_REVIEW',"internalNotes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL); CREATE INDEX "CustomRequest_status_createdAt_idx" ON "CustomRequest"("status","createdAt");
CREATE TABLE "ReferenceImage"("id" TEXT PRIMARY KEY,"requestId" TEXT NOT NULL REFERENCES "CustomRequest"("id") ON DELETE CASCADE,"storageKey" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"size" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "BusinessSettings"("id" INTEGER PRIMARY KEY DEFAULT 1,"name" TEXT NOT NULL DEFAULT 'Maa''s Stitch & Style',"description" TEXT NOT NULL DEFAULT 'Stitched with Love. Styled by You.',"whatsappNumber" TEXT,"phone" TEXT,"email" TEXT,"instagramUrl" TEXT,"deliveryAreas" TEXT[] NOT NULL DEFAULT ARRAY['Rajahmundry']::TEXT[],"pickupInfo" TEXT,"currency" TEXT NOT NULL DEFAULT 'INR',"updatedAt" TIMESTAMP(3) NOT NULL);
